"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { cn } from "@/lib/utils"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-bg:oklch(1 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-card:oklch(1 0 0);--chatcn-ease-out:cubic-bezier(0.23, 1, 0.32, 1);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-gray-100:oklch(0.970 0 0);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-400:oklch(0.910 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-radius-lg:12px;--chatcn-shadow-sm:0 0 0 1px oklch(0 0 0 / 0.06), 0 1px 2px -1px oklch(0 0 0 / 0.06), 0 2px 4px oklch(0 0 0 / 0.04)}.dark{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-bg:oklch(0.145 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-card:oklch(0.175 0 0);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-gray-100:oklch(0.195 0 0);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-400:oklch(0.285 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-shadow-sm:0 0 0 1px oklch(1 0 0 / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.03), 0 2px 4px oklch(0 0 0 / 0.4)}.chatcn-shimmer{color: transparent; background-image: linear-gradient(90deg, var(--chatcn-fg-subtle) 0%, var(--chatcn-fg-subtle) 40%, var(--chatcn-fg) 50%, var(--chatcn-fg-subtle) 60%, var(--chatcn-fg-subtle) 100%); background-size: 250% 100%; background-clip: text; -webkit-background-clip: text; animation: chatcn-shimmer 1.6s linear infinite;}@keyframes chatcn-shimmer { from { background-position: 100% 0; } to { background-position: 0% 0; } }@media (prefers-reduced-motion: reduce){.chatcn-shimmer{animation:none;color:var(--chatcn-fg-subtle);background-image:none}}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-thinking-indicator")) {
  const style = document.createElement("style")
  style.id = "chatcn-thinking-indicator"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Timing
 * -----------------------------------------------------------------------------------------------*/

/**
 * Delayed presence for loaders: stays hidden for `delay` ms after `active` turns on, and once
 * shown stays for at least `minDuration` ms. A wait shorter than the delay shows nothing at all,
 * so the indicator can never flash.
 */
export function useDelayedPresence(active: boolean, delay = 300, minDuration = 400) {
  const [shown, setShown] = React.useState(false)
  const shownAt = React.useRef(0)

  React.useEffect(() => {
    if (active && !shown) {
      const id = window.setTimeout(() => {
        shownAt.current = Date.now()
        setShown(true)
      }, delay)
      return () => window.clearTimeout(id)
    }
    if (!active && shown) {
      const left = minDuration - (Date.now() - shownAt.current)
      if (left <= 0) {
        setShown(false)
        return
      }
      const id = window.setTimeout(() => setShown(false), left)
      return () => window.clearTimeout(id)
    }
  }, [active, shown, delay, minDuration])

  return shown
}

/* -------------------------------------------------------------------------------------------------
 * ThinkingIndicator
 * -----------------------------------------------------------------------------------------------*/

export type ThinkingIndicatorVariant = "label" | "timer" | "motif"

export interface ThinkingIndicatorProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** True while the model is working and nothing visible has arrived yet. Defaults to true. */
  active?: boolean
  /** `label` is the shimmer word, `timer` adds elapsed seconds, `motif` is the square alone. */
  variant?: ThinkingIndicatorVariant
  /** The status word. Defaults to "Thinking". Use a verb for the current step: "Searching". */
  label?: string
  /** Epoch ms when the wait began, for the timer. Defaults to when `active` turned on. */
  startedAt?: number
  /** Hidden for this long after `active` turns on. Defaults to 300 ms. */
  delay?: number
  /** Once shown, stays at least this long. Defaults to 400 ms. */
  minDuration?: number
}

/** Seconds since `since`, ticking once per second while `running`. */
function useSeconds(since: number | undefined, running: boolean) {
  // Starts empty and reads the clock after mount: a render must not read it (Next.js prerender).
  const [now, setNow] = React.useState<number | null>(null)
  React.useEffect(() => {
    if (!running) return
    setNow(Date.now())
    const id = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(id)
  }, [running])
  return since === undefined || now === null ? 0 : Math.max(0, now - since)
}

type StreamingCaretStatus = "streaming" | "waiting" | "done"

interface StreamingCaretProps extends Omit<React.ComponentProps<"span">, "children"> {
  /**
   * `streaming` is solid, `waiting` blinks slowly, `done` removes the caret. Defaults to
   * `streaming`.
   */
  status?: StreamingCaretStatus
  /**
   * Pass the streamed text (or anything that changes with each token). While it keeps changing
   * the caret stays solid; once it holds still for `idleMs` the caret starts to blink.
   */
  activity?: unknown
  /** Quiet time before the caret switches to blinking. Defaults to 600 ms. */
  idleMs?: number
}

/**
 * The signature mark: a small rounded square that means "the model is writing here". It sits on
 * the text baseline at 0.55em, so it scales with whatever text it follows. Solid while tokens flow,
 * a slow 1.2 s blink only while waiting, gone when done. Static under reduced motion.
 */
function StreamingCaret({
  status = "streaming",
  activity,
  idleMs = 600,
  className,
  ...props
}: StreamingCaretProps) {
  const [idle, setIdle] = React.useState(false)
  const tracking = activity !== undefined && status === "streaming"

  React.useEffect(() => {
    if (!tracking) return
    setIdle(false)
    const id = window.setTimeout(() => setIdle(true), idleMs)
    return () => window.clearTimeout(id)
  }, [activity, tracking, idleMs])

  if (status === "done") return null
  const blinking = status === "waiting" || (tracking && idle)

  return (
    <span
      aria-hidden="true"
      data-slot="streaming-caret"
      data-caret-state={blinking ? "waiting" : "streaming"}
      className={cn(
        "bg-(color:--chatcn-accent) ms-0.5 inline-block size-[0.55em] translate-y-[0.04em] rounded-[0.12em] align-baseline forced-colors:bg-[CanvasText]",
        blinking &&
          "animate-[chatcn-caret-blink_1.2s_steps(1,end)_infinite] motion-reduce:animate-none",
        className,
      )}
      {...props}
    />
  )
}

/**
 * The only shimmer in chatcn: a status label such as "Thinking". Static under reduced motion.
 * Pass `active={false}` to settle it into plain subtle text.
 */
function ShimmerText({
  active = true,
  className,
  ...props
}: React.ComponentProps<"span"> & { active?: boolean }) {
  return (
    <span
      data-slot="shimmer-text"
      className={cn("font-medium", active ? "chatcn-shimmer" : "text-(color:--chatcn-fg-subtle)", className)}
      {...props}
    />
  )
}

const NBSP = "\u00a0"

function formatElapsed(ms: number) {
  const s = Math.floor(ms / 1000)
  if (s < 60) return `${s}${NBSP}s`
  if (s < 3600) return `${Math.floor(s / 60)}${NBSP}m ${s % 60}${NBSP}s`
  return `${Math.floor(s / 3600)}${NBSP}h ${Math.floor((s % 3600) / 60)}${NBSP}m`
}

/**
 * Pending state before the first token. Shows nothing for 300 ms (the sent message is the
 * feedback), then a shimmering "Thinking" that stays at least 400 ms so it never flashes.
 */
export function ThinkingIndicator({
  active = true,
  variant = "label",
  label = "Thinking",
  startedAt,
  delay = 300,
  minDuration = 400,
  className,
  ...props
}: ThinkingIndicatorProps) {
  const shown = useDelayedPresence(active, delay, minDuration)
  const [since, setSince] = React.useState<number>()
  React.useEffect(() => {
    if (active) setSince((s) => s ?? Date.now())
    else setSince(undefined)
  }, [active])
  const elapsed = useSeconds(startedAt ?? since, shown && variant === "timer")

  return (
    <div
      role="status"
      data-slot="thinking-indicator"
      data-variant={variant}
      data-visible={shown ? "" : undefined}
      // Hidden, it keeps no space but stays mounted, so the live region announces reliably.
      className={cn(shown ? "text-[0.875rem]/[1.25rem] tracking-[-0.003em] flex h-6 items-center gap-2" : "sr-only", className)}
      {...props}
    >
      {shown ? (
        <span
          className={cn(
            "inline-flex items-center gap-2",
            "ease-(--chatcn-ease-out) transition-opacity duration-150 starting:opacity-0",
          )}
        >
          {variant === "motif" ? (
            <>
              <StreamingCaret status="waiting" className="text-[1rem]/[1.5rem] tracking-[-0.01em] ms-0" />
              <span className="sr-only">{label}</span>
            </>
          ) : (
            <>
              <ShimmerText>{label}</ShimmerText>
              {variant === "timer" && elapsed >= 1000 ? (
                <span aria-hidden="true" className="text-(color:--chatcn-fg-subtle) tabular-nums">
                  {formatElapsed(elapsed)}
                </span>
              ) : null}
            </>
          )}
        </span>
      ) : null}
    </div>
  )
}

export default ThinkingIndicator

